-- =============================================================================
-- Demo Counterparty Logo Template
--
-- Seeds a single system-tenant "template" row in ores_assets_images_tbl for
-- the counterparty-logo demo: Acme Corporation is a party (the synthetic
-- holding-group tenant under test), not itself a counterparty, so there is
-- no "Acme Corp" counterparty to attach a logo to -- the demo instead
-- attaches a real logo to one of the real GLEIF counterparties Acme
-- Corporation trades with (BARCLAYS PLC, short_code BRCLYS, from the
-- 'gleif.lei_counterparties.small' import). Logo sourced from Wikimedia
-- Commons (File:Barclays-Logo.svg, CC0 -- public domain), vendored at
-- external/barclays/Barclays-logo.svg.
--
-- This is an SVG asset, but still bypasses the SVG-only
-- ores_dq_images_artefact_tbl staging pipeline (see the "Generalise account
-- images" task) since it isn't part of a bulk flag/icon dataset -- it is
-- inserted directly into ores_assets_images_tbl under the system tenant,
-- then copied per-tenant and attached by tenant_handler::provision_acme
-- (ores.iam.core/messaging/tenant_handler.hpp). Idempotent: skips if a
-- system-tenant row with this key already exists.
-- =============================================================================

DO $$
BEGIN
    if not exists (
        select 1 from ores_assets_images_tbl
        where tenant_id = ores_utility_system_tenant_id_fn()
          and key = 'demo_counterparty_logo'
          and valid_to = ores_utility_infinity_timestamp_fn()
    ) then
        insert into ores_assets_images_tbl (
            image_id, tenant_id, version, key, description, mime_type, data,
            modified_by, performed_by, change_reason_code, change_commentary
        ) values (
            gen_random_uuid(), ores_utility_system_tenant_id_fn(), 0,
            'demo_counterparty_logo', 'Barclays plc logo (Wikimedia Commons, CC0)',
            'image/svg+xml',
            $b64$$b64$,
            coalesce(ores_iam_current_service_fn(), current_user), current_user,
            'system.external_data_import',
            'Vendored from external/barclays/Barclays-logo.svg (Wikimedia Commons, CC0)'
        );
    end if;
END $$;
